DO $$ DECLARE def text;BEGIN SELECT pg_get_functiondef('public.finance_reconciliation_rows(uuid,date)'::regprocedure) INTO def;def:=replace(def,'snapshot text;','v_snapshot text;');def:=replace(def,'snapshot:=md5','v_snapshot:=md5');def:=replace(def,'finance_reconciliation_explanations.snapshot=snapshot','finance_reconciliation_explanations.snapshot=v_snapshot');def:=replace(def,'''snapshot'',snapshot','''snapshot'',v_snapshot');EXECUTE def;END $$;